import re

with open('index.html', 'r', encoding='utf-8') as f:
    idx = f.read()

idx = re.sub(
    r'<div class="swiper-wrapper">[\s\S]*?<!-- Navigation Buttons -->',
    slides_block + '\n\n            <!-- Navigation Buttons -->',
    idx
)

with open('index.html', 'w', encoding='utf-8') as f:
    f.write(idx)

print('Restored all 3 slides properly.')
